package com.cbdog.ptvbox
import org.junit.Test
import org.junit.Assert.*
import java.util.zip.*
class MediaText053Test {
 @Test fun srtVttAndAssTimeAndText(){val s="1\n00:00:01,250 --> 00:00:03,000\n你好\nHello\n\n";val cue=MediaText053.cues(s).single();assertEquals(1250,cue.start);assertEquals("你好\nHello",cue.text);assertEquals(3000,cue.end);assertEquals(4200,MediaText053.cues("WEBVTT\n\n00:04.200 --> 00:06.000 position:50%\nHi\n").single().start);assertEquals("中文\nEnglish",MediaText053.cues("Dialogue: 0,0:00:01.20,0:00:05.50,Default,,0,0,0,,{\\b1}中文\\NEnglish").single().text)}
 @Test fun htmlAndInvalidFilesDoNotLoad(){assertTrue(MediaText053.cues("<!DOCTYPE html><html>login</html>").isEmpty());assertTrue(runCatching{MediaText053.unpack("<html>503</html>".toByteArray(),"test.srt")}.isFailure);assertTrue(MediaText053.cues("1\n00:00:05,000 --> 00:00:01,000\nInvalid").isEmpty())}
 @Test fun zipReadsBytesWithoutExtractingPaths(){val out=java.io.ByteArrayOutputStream();ZipOutputStream(out).use{it.putNextEntry(ZipEntry("../../outside.srt"));it.write("1\n00:00:01,000 --> 00:00:03,000\n字幕\n".toByteArray());it.closeEntry()};val read=MediaText053.unpack(out.toByteArray(),"pack.zip");assertEquals("outside.srt",read.single().first);assertEquals("字幕",MediaText053.cues(read.single().second).single().text)}
 @Test fun legacyChineseAndUtf16(){val s="1\n00:00:01,000 --> 00:00:03,000\n中文字幕\n";assertEquals(s,MediaText053.decode(s.toByteArray(charset("GB18030"))));assertEquals(s,MediaText053.decode(byteArrayOf(0xff.toByte(),0xfe.toByte())+s.toByteArray(Charsets.UTF_16LE)))}
 @Test fun wrongSeasonEpisodeEditionAndYearRejected(){val c=MediaContext053(Work("a","攻壳机动队","tv","2026",season=1),8);assertFalse(c.accepts("Ghost in the Shell SAC 2045 S01E08"));assertFalse(c.accepts("攻壳机动队 S01E07"));assertFalse(c.accepts("攻壳机动队 S02E08"));assertTrue(c.accepts("攻壳机动队 S01E08"));assertFalse(MediaContext053(Work("b","The Odyssey","movie","2026"),null).accepts("The Odyssey 1997"));assertFalse(c.accepts("攻壳机动队 making of"))}
 @Test fun danmakuJsonAndXmlAndNoEntities(){val json=MediaText053.danmaku("""{"comments":[{"p":"1.5,1,16711680,u","m":"测试"}]}""").single();assertEquals(1500,json.time);assertEquals(0xff0000,json.color);val xml=MediaText053.danmaku("""<i><d p="2.0,5,25,65280">顶部</d></i>""").single();assertEquals(5,xml.mode);assertEquals(65280,xml.color);assertTrue(runCatching{MediaText053.danmaku("<!DOCTYPE i [<!ENTITY a SYSTEM 'file:///secret'>]><i><d p='1'>&a;</d></i>")}.isFailure)}
 @Test fun boundedInputFailsRatherThanTruncates(){assertTrue(runCatching{MediaText053.bounded(ByteArray(100).inputStream(),99)}.isFailure);assertEquals(100,MediaText053.bounded(ByteArray(100).inputStream(),100).size)}
 @Test fun credentialTransportErrorsNeverEchoHeadersOrUrls(){assertFalse(mediaError053(IllegalArgumentException("Unexpected char in Api-Key value qa-private-secret")).contains("qa-private-secret"));assertFalse(mediaError053(java.io.IOException("Unable to connect https://api.example/sub?token=qa-secret")).contains("qa-secret"));assertTrue(mediaError053(java.io.IOException("OpenSubtitles获取下载链接 HTTP 503（网关/CDN），请等待30后重试")).contains("503"))}
}
